(() => {
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const page = document.body.dataset.page;
const admin = ['dashboard','admin-menu','admin-orders','customers','reports'].includes(page);
const money = n => 'Rp' + Number(n).toLocaleString('id-ID');
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read = (k, fallback) => { try { return JSON.parse(localStorage.getItem('menteng-'+k)) ?? fallback; } catch { return fallback; } };
const save = (k,v) => localStorage.setItem('menteng-'+k, JSON.stringify(v));
const icons = {bag:'<path d="M6 7h12l2 14H4L6 7Z"/><path d="M9 8V6a3 3 0 0 1 6 0v2"/>',arrow:'<path d="m9 5 7 7-7 7"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',truck:'<path d="M2 5h12v12H2zM14 9h4l4 5v3h-8"/><circle cx="6" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',leaf:'<path d="M20 3C7 1 1 10 6 17s17 2 14-14ZM5 20 16 9"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',chart:'<path d="M4 3v18h18M8 16v-4m5 4V7m5 9V4"/>'};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.leaf}</svg>`;
const brand = `<a href="/" class="brand"><img src="/images/brand.svg" alt="" width="45" height="45"><span>Dapur Menteng<small>Nasi uduk & catering</small></span></a>`;
const baseMenus = [
{id:1,name:'Nasi Uduk Ayam Goreng',category:'satuan',price:25000,min:1,image:'hero.jpg',desc:'Nasi uduk gurih, ayam goreng, bihun, tempe orek, sambal, dan kerupuk.'},
{id:2,name:'Nasi Uduk Telur Balado',category:'satuan',price:18000,min:1,image:'box.jpg',desc:'Nasi uduk, telur balado, bihun, tempe orek, dan kerupuk.'},
{id:3,name:'Nasi Uduk Ayam Bakar',category:'satuan',price:28000,min:1,image:'satuan.jpg',desc:'Nasi uduk, ayam bakar, tahu, lalapan segar, dan sambal.'},
{id:4,name:'Nasi Box Ayam Goreng',category:'box',price:30000,min:10,image:'satuan.jpg',desc:'Nasi uduk, ayam goreng, bihun, tempe orek, sambal, dan kerupuk dalam kemasan box.'},
{id:5,name:'Nasi Box Komplet',category:'box',price:38000,min:10,image:'hero.jpg',desc:'Nasi uduk, ayam, telur balado, bihun, tempe orek, sambal, dan kerupuk.'},
{id:6,name:'Nasi Box Telur Balado',category:'box',price:23000,min:10,image:'box.jpg',desc:'Nasi uduk dan telur balado dengan bihun, orek tempe, sambal, dan kerupuk.'},
{id:7,name:'Prasmanan Paket A',category:'prasmanan',price:40000,min:30,image:'prasmanan.jpg',desc:'Nasi uduk, ayam goreng, telur balado, tumis sayur, bihun, sambal, dan kerupuk.'},
{id:8,name:'Prasmanan Paket B',category:'prasmanan',price:50000,min:30,image:'hero.jpg',desc:'Nasi uduk, ayam bakar, rendang, sayur, bihun, sambal, dan kerupuk.'},
{id:9,name:'Prasmanan Paket Keluarga',category:'prasmanan',price:35000,min:30,image:'box.jpg',desc:'Nasi uduk dan lauk rumahan untuk acara keluarga.',available:false}
].map(m=>({available:true,...m}));
const sData = window.__SERVER_DATA__ || {};
const serverMenus = (sData.menus && sData.menus.length)
  ? sData.menus.map(m=>({id:m.id,name:m.nama_menu||m.name,category:m.kategori?.slug||m.category?.slug||m.jenis_paket||m.package_type,price:Number(m.harga||m.price),min:m.minimal_pesanan||m.min_order,image:m.foto_menu||m.image_path,desc:m.deskripsi||m.description,available:Boolean(m.status_tersedia!==undefined?m.status_tersedia:m.is_available)}))
  : null;
let menus=serverMenus||read('menus',baseMenus), cart=read('cart',[]), user=sData.user?{id:sData.user.id,name:sData.user.nama||sData.user.name||'',nama:sData.user.nama||sData.user.name||'',email:sData.user.email,phone:sData.user.nomor_telepon||sData.user.phone||'',nomor_telepon:sData.user.nomor_telepon||sData.user.phone||'',address:sData.user.alamat||sData.user.address||'',alamat:sData.user.alamat||sData.user.address||'',role:sData.user.peran||sData.user.role||'customer',peran:sData.user.peran||sData.user.role||'customer'}:null;
const today = () => new Date().toLocaleDateString('en-CA');
const tomorrow = () => {const d=new Date();d.setDate(d.getDate()+1);return d.toLocaleDateString('en-CA');};
const date = s => new Date(s+'T12:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'});
const cats = {satuan:'Porsi satuan',box:'Nasi box',prasmanan:'Prasmanan'};
const states=['Menunggu pembayaran','Diproses dapur','Dikirim / siap diambil','Selesai'];
const customers=[{name:'Siti Rahma',email:'siti@contoh.test',phone:'081234567890'},{name:'Budi Santoso',email:'budi@contoh.test',phone:'081298765432'},{name:'Dewi Lestari',email:'dewi@contoh.test',phone:'081355667788'},{name:'Andi Pratama',email:'andi@contoh.test',phone:'081388990011'}];
const seedOrders=[['0001',0,4,10,'Menunggu verifikasi',0],['0002',1,7,30,'Lunas',1],['0003',2,8,30,'Lunas',2],['0004',0,1,4,'Ditolak',0],['0005',0,4,20,'Lunas',3],['0006',1,8,40,'Lunas',3]].map(([id,c,m,q,p,s],i)=>{const menu=baseMenus.find(x=>x.id===m);return {id:'DM-261105-'+id,name:customers[c].name,email:customers[c].email,phone:customers[c].phone,date:'2026-11-'+String(5-i%5).padStart(2,'0'),deliveryDate:tomorrow(),time:'10:00',method:'delivery',address:'Jl. Cikini Raya No. 12, Menteng, Jakarta Pusat',items:[{...menu,qty:q,note:'Sambal dipisah'}],fee:15000,payment:p,status:s,proof:p==='Menunggu verifikasi'?'bukti-transfer-contoh.png':null};});
let serverOrders = null;
if (sData.orders && sData.orders.length) {
    serverOrders = sData.orders.map(o => ({
        id: o.nomor_pesanan || o.order_number || ('DM-' + o.id),
        name: o.nama_penerima || o.recipient_name,
        email: o.email_penerima || o.recipient_email || (o.user?.email || o.pengguna?.email || ''),
        phone: o.nomor_telepon_penerima || o.recipient_phone,
        date: String(o.tanggal_pesanan || o.order_date || o.created_at || '').slice(0, 10),
        deliveryDate: String(o.tanggal_pengiriman || o.delivery_date || '').slice(0, 10),
        time: o.waktu_pengiriman || o.delivery_time || '10:00',
        method: o.jenis_pengiriman || o.delivery_type || 'delivery',
        address: o.alamat_pengiriman || o.delivery_address || 'Ambil di dapur',
        items: (o.items || []).map(it => ({
            id: it.id_menu || it.menu_id,
            name: it.nama_menu || it.menu_name,
            price: Number(it.harga || it.price),
            qty: it.kuantitas || it.quantity,
            note: it.catatan || it.notes || '',
            image: it.menu?.foto_menu || it.menu?.image_path || 'hero.jpg',
        })),
        fee: Number(o.biaya_pengiriman ?? o.delivery_fee ?? 0),
        payment: o.status_pembayaran || o.payment_status || 'Menunggu pembayaran',
        status: Number(o.status_pesanan ?? o.order_status ?? 0),
        proof: o.payment?.bukti_transfer || o.payment?.proof_image || null,
        rejection: o.payment?.catatan_penolakan || o.payment?.rejection_note || null,
    }));
}
let orders=serverOrders||read('orders',seedOrders);
let activeCategory=new URLSearchParams(location.search).get('kategori')||'satuan';
if(!cats[activeCategory]) activeCategory='satuan';
const total = items => items.reduce((a,x)=>a+x.price*x.qty,0);
const badge = text => `<span class="badge ${text==='Lunas'||text==='Selesai'?'success':text==='Ditolak'?'danger':''}">${esc(text)}</span>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function showModal(content){$('#modal-content').innerHTML=content;$('#modal').showModal();}
function header(){
 $('#site-header').innerHTML=`<div class="header-inner">${brand}<button class="icon-button mobile-toggle" data-action="nav" aria-label="Buka navigasi" aria-expanded="false">☰</button><nav id="navigation" aria-label="Navigasi utama">${admin?'<span class="admin-label">Panel administrasi</span><a href="/">Lihat website</a>':`<a href="/" ${page==='home'?'aria-current="page"':''}>Beranda</a><a href="/menu" ${page==='catalog'?'aria-current="page"':''}>Pilihan menu</a><a href="/#cara-pesan">Cara pesan</a><a href="/#pengiriman">Pengiriman</a>`}</nav><div class="header-actions">${admin?'<span class="avatar">A</span><span>Admin dapur</span>':`<a class="cart-link" href="/keranjang" aria-label="Keranjang">${icon('bag')}<span class="cart-count">${cart.reduce((a,x)=>a+x.qty,0)}</span></a>${user?`<a class="account-link" href="${(user.peran==='admin'||user.role==='admin')?'/admin':'/pesanan'}">${esc(((user.nama||user.name||'Pelanggan')).split(' ')[0])}</a><button class="text-button" data-action="logout">Keluar</button>`:'<a class="login-link" href="/login">Masuk</a><a href="/menu" class="button small">Pesan sekarang</a>'}`}</div></div>`;
 $('#site-footer').innerHTML=admin?'':`<div class="container footer-top"><div>${brand}<p>Masakan dari dapur kami,<br>untuk hangatnya kebersamaan Anda.</p></div><div><h3>Jelajahi</h3><a href="/menu">Pilihan menu</a><a href="/#cara-pesan">Cara pesan</a><a href="/pesanan">Pesanan saya</a></div><div><h3>Dapur kami</h3><p>Menteng, Jakarta Pusat<br>Delivery hingga radius 20 km<br>Pesan paling lambat H-1</p></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Dapur Menteng</span><span>Dimasak hari ini. Dinikmati bersama.</span><a href="/admin">Panel admin</a></div>`;
 if(admin){document.body.classList.add('admin');const links=[['dashboard','/admin','grid','Ringkasan'],['admin-menu','/admin/menu','leaf','Menu & paket'],['admin-orders','/admin/pesanan','bag','Pesanan'],['customers','/admin/pelanggan','users','Pelanggan'],['reports','/admin/laporan','chart','Laporan penjualan']];$('#page-layout').insertAdjacentHTML('afterbegin',`<aside class="sidebar"><p>Operasional dapur</p><nav aria-label="Navigasi admin">${links.map(([p,url,i,l])=>`<a href="${url}" ${page===p?'aria-current="page"':''}>${icon(i)}${l}</a>`).join('')}</nav><div class="sidebar-note">${icon('leaf')}<b>Dapur Menteng</b><span>Selamat memasak,<br>selamat melayani.</span></div></aside>`);}
}
function heading(title,desc,action=''){return `<div class="page-heading"><div><a class="breadcrumb" href="${admin?'/admin':'/'}">${admin?'Dapur Menteng / Operasional':'Beranda / Pemesanan'}</a><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function steps(n){return `<ol class="checkout-steps">${['Keranjang','Checkout','Pembayaran','Lacak pesanan'].map((s,i)=>`<li class="${i===n?'current':i<n?'done':''}"><span>${i<n?'✓':i+1}</span>${s}</li>`).join('')}</ol>`;}
const button=(url,label,cls='')=>`<a href="${url}" class="button ${cls}">${label}</a>`;
function home(){return `<section class="hero container"><div class="hero-copy"><div class="origin">${icon('pin')} Dari dapur Menteng, Jakarta</div><h1>Ada nasi uduk.<br>Ada cerita<br>di meja makan.</h1><p>Gurih santannya, lengkap lauknya. Dari sarapan sendiri sampai hajatan keluarga, kami siapkan untuk momen Anda.</p><div class="hero-buttons">${button('/menu','Pilih menu & pesan '+icon('arrow'))}<a class="plain-link" href="#cara-pesan">Lihat cara pesan</a></div><div class="hero-note">${icon('clock')} Dimasak di hari acara. Pesan minimal H-1.</div></div><figure class="hero-visual"><img src="/images/hero.jpg" alt="Sajian nasi uduk dengan ayam goreng, telur, sambal, dan lalapan di atas daun pisang" fetchpriority="high"><div class="food-tag">Resep rumahan.<br>Rasa yang dirindukan.<span>Sehangat makan di rumah</span></div><figcaption>${icon('leaf')} Nasi uduk & lauk pilihan</figcaption></figure></section><section class="service-strip container" aria-label="Informasi layanan"><div>${icon('leaf')}<span><b>Tiga cara menikmati</b><small>Porsi satuan, nasi box & prasmanan</small></span></div><div>${icon('truck')}<span><b>Kami antar ke tempat Anda</b><small>Hingga 20 km dari Menteng, Jakarta</small></span></div><div>${icon('bag')}<span><b>Mau ambil sendiri? Bisa.</b><small>Pick-up di dapur, tanpa ongkir</small></span></div></section><section class="section container" id="pilihan-menu"><div class="section-heading"><div><h2>Untuk setiap meja,<br>ada pilihan sajiannya.</h2><p>Makan sendiri, rapat kantor, atau kumpul satu keluarga.</p></div><a class="plain-link" href="/menu">Jelajahi semua menu ${icon('arrow')}</a></div><div class="category-grid">${[['satuan','satuan.jpg','Porsi satuan','Teman sarapan dan makan siang, dengan lauk yang Anda suka.',18000,1],['box','box.jpg','Nasi box','Rapi dalam kotak. Praktis untuk rapat, pengajian, dan berbagi.',23000,10],['prasmanan','prasmanan.jpg','Prasmanan','Hidangan lengkap untuk merayakan momen bersama.',40000,30]].map(([c,img,t,d,p,m])=>`<a href="/menu?kategori=${c}" class="category-card"><div class="category-image"><img src="/images/${img}" alt="Ilustrasi sajian ${t.toLowerCase()}" loading="lazy"><span>Mulai ${m} porsi</span></div><div class="category-content"><h3>${t} ${icon('arrow')}</h3><p>${d}</p><div>Mulai <b>${money(p)}</b><small> / porsi</small></div></div></a>`).join('')}</div><p class="photo-note">Foto merupakan ilustrasi penyajian. Komposisi mengikuti menu pilihan.</p></section><section class="how-section" id="cara-pesan"><div class="container"><div class="section-heading"><h2>Anda rencanakan acaranya.<br>Kami siapkan hidangannya.</h2><p>Pesan dari rumah,<br>tenang sampai hari acara.</p></div><ol class="how-grid">${[['Pilih menu & porsi','Cari lauk favorit, tentukan porsi, lalu masukkan ke keranjang.'],['Tentukan jadwal','Isi tanggal acara dan pilih diantar atau ambil di dapur.'],['Selesaikan pembayaran','Transfer melalui BCA atau Mandiri, lalu unggah buktinya.'],['Tunggu hidangan Anda','Pantau pesanan dari dapur hingga siap dinikmati.']].map(([t,d],i)=>`<li><span>${i+1}</span><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol></div></section><section class="section container delivery-section" id="pengiriman"><div class="delivery-art"><div class="delivery-circle">${icon('pin')}<strong>Menteng</strong><span>Jakarta Pusat</span></div><span class="radius-label">Dari dapur, hingga 20 km</span><span class="map-place place-one">Gambir</span><span class="map-place place-two">Cikini</span><span class="map-place place-three">Tanah Abang</span></div><div><h2>Sampai di meja Anda,<br>sesuai waktunya.</h2><p>Pilih cara menerima hidangan yang paling nyaman. Semua disiapkan segar pada hari acara.</p><div class="delivery-option">${icon('truck')}<div><h3>Diantar ke lokasi</h3><p>Dalam radius 20 km dari Dapur Menteng. Ongkir dihitung saat checkout.</p></div></div><div class="delivery-option">${icon('bag')}<div><h3>Ambil langsung di dapur</h3><p>Datang sesuai tanggal dan jam pilihan Anda. Tanpa biaya pengiriman.</p></div></div></div></section><section class="container closing-cta"><div><h2>Meja sudah siap.<br>Tinggal pilih hidangannya.</h2><p>Mulai dari seporsi, sampai untuk satu acara.</p></div>${button('/menu','Lihat pilihan menu '+icon('arrow'),'yellow')}</section>`;}
function menuCard(m){return `<article class="menu-card"><button class="menu-image" data-action="detail" data-id="${m.id}" aria-label="Lihat detail ${esc(m.name)}"><img src="/images/${m.image}" alt="Ilustrasi ${esc(m.name)}" loading="lazy"><span>Min. ${m.min} porsi</span></button><div class="menu-content"><small>${cats[m.category]}</small><h2>${esc(m.name)}</h2><p>${esc(m.desc)}</p><div class="menu-price"><div><strong>${money(m.price)}</strong><small> / porsi</small></div><button class="add-button" data-action="detail" data-id="${m.id}" aria-label="Tambah ${esc(m.name)}">+</button></div></div></article>`;}
function catalog(){const list=menus.filter(m=>m.available&&m.category===activeCategory);return `<div class="container page-content">${heading('Mau makan apa hari ini?','Pilih hidangan favorit. Kami siapkan dengan lauk yang lengkap.')}<div class="notice">${icon('clock')}<span>Pesan minimal H-1 <span class="notice-separator">|</span> Delivery hingga 20 km dari Menteng <span class="notice-separator">|</span> Tersedia pick-up</span></div><div class="catalog-toolbar"><div class="tabs" role="group" aria-label="Kategori menu">${Object.entries(cats).map(([c,n])=>`<button data-action="category" data-category="${c}" aria-pressed="${activeCategory===c}">${n}</button>`).join('')}</div><label class="search-box">${icon('search')}<input id="menu-search" type="search" placeholder="Cari menu atau lauk…" aria-label="Cari menu atau lauk"></label></div><div class="menu-grid" id="menu-grid">${list.map(menuCard).join('')}</div><p class="photo-note">Foto merupakan ilustrasi penyajian. Harga per porsi; minimum pesanan berlaku untuk setiap menu.</p></div>`;}
function detail(id){const m=menus.find(x=>x.id===id);if(!m||!m.available)return;showModal(`<div class="detail-image"><img src="/images/${m.image}" alt="Ilustrasi ${esc(m.name)}"></div><form id="add-form" data-id="${id}" class="detail-content"><small>${cats[m.category]}</small><h2 id="modal-title">${esc(m.name)}</h2><p>${esc(m.desc)}</p><strong class="detail-price">${money(m.price)} <small>/ porsi</small></strong><label>Jumlah porsi<input name="qty" type="number" min="${m.min}" value="${m.min}" step="1" required></label><small>Minimal pemesanan ${m.min} porsi.</small><label>Catatan untuk dapur <span>(opsional)</span><textarea name="note" placeholder="Misalnya, sambal dipisah" maxlength="500" rows="2"></textarea></label><button class="button full" type="submit">${icon('bag')} Tambah ke keranjang</button></form>`);}
function cartPage(){return `<div class="container page-content">${heading('Keranjang Anda','Periksa porsi dan catatan sebelum kami siapkan hidangannya.')} ${steps(0)}${!cart.length?empty('Keranjang masih kosong','Pilih nasi uduk dan lauk favorit untuk memulai pesanan.','/menu','Pilih menu'): `<div class="two-column"><section class="panel cart-panel"><div class="panel-heading"><h2>Menu pilihan (${cart.length})</h2><a href="/menu" class="plain-link">Tambah menu</a></div>${cart.map((x,i)=>`<article class="cart-item"><img src="/images/${x.image}" alt="Ilustrasi ${esc(x.name)}"><div class="cart-item-body"><h3>${esc(x.name)}</h3><p>${money(x.price)} / porsi <span>· Min. ${x.min} porsi</span></p><div class="quantity"><button data-action="qty" data-index="${i}" data-delta="-1" aria-label="Kurangi porsi ${esc(x.name)}" ${x.qty<=x.min?'disabled':''}>−</button><input type="number" value="${x.qty}" min="${x.min}" data-cart-qty="${i}" aria-label="Jumlah porsi ${esc(x.name)}"><button data-action="qty" data-index="${i}" data-delta="1" aria-label="Tambah porsi ${esc(x.name)}">+</button></div><label>Catatan dapur<textarea data-cart-note="${i}" rows="2" maxlength="500" placeholder="Sambal dipisah, misalnya">${esc(x.note)}</textarea></label><button class="text-button remove" data-action="remove" data-index="${i}">Hapus menu</button></div><b>${money(x.qty*x.price)}</b></article>`).join('')}</section>${summary(cart,0,button('/checkout','Lanjut ke checkout '+icon('arrow'),'full'),true)}</div>`}</div>`;}
function empty(t,d,url,label){return `<div class="empty-state">${icon('bag')}<h2>${t}</h2><p>${d}</p>${url?button(url,label):''}</div>`;}
function summary(items,fee,action,temporary=false){return `<aside class="panel summary"><h2>Ringkasan pesanan</h2>${items.map(x=>`<div class="summary-row"><span>${esc(x.name)}<small>${x.qty} × ${money(x.price)}</small></span><b>${money(x.qty*x.price)}</b></div>`).join('')}<hr><div class="summary-row"><span>Subtotal menu</span><span>${money(total(items))}</span></div><div class="summary-row"><span>Ongkos kirim</span><span id="shipping-cost">${temporary?'Saat checkout':money(fee)}</span></div><div class="summary-total"><span>${temporary?'Total sementara':'Total tagihan'}</span><b id="grand-total">${money(total(items)+fee)}</b></div>${action}<p class="summary-note">${icon('clock')} Pesan minimal H-1 agar hidangan bisa kami siapkan segar.</p></aside>`;}
function checkout(){if(!cart.length)return `<div class="container page-content">${heading('Checkout','Lengkapi detail pesanan Anda.')}${empty('Belum ada menu dipilih','Tambahkan menu ke keranjang sebelum checkout.','/menu','Pilih menu')}</div>`;return `<div class="container page-content">${heading('Sedikit lagi, siap dipesan.','Lengkapi penerima, jadwal, dan cara menerima hidangan.')} ${steps(1)}<form id="checkout-form" class="two-column"><div><section class="panel form-panel"><h2>Informasi penerima</h2><div class="form-grid"><label>Nama penerima<input name="name" autocomplete="name" value="${esc(user?.name||'')}" required></label><label>Nomor WhatsApp<input name="phone" type="tel" autocomplete="tel" pattern="[0-9+ ()-]{9,18}" placeholder="08xxxxxxxxxx" value="${esc(user?.phone||'')}" required></label></div></section><section class="panel form-panel"><h2>Kapan hidangan dibutuhkan?</h2><p class="muted">Pesan minimal sehari sebelum acara.</p><div class="form-grid"><label>Tanggal acara<input type="date" name="deliveryDate" min="${tomorrow()}" value="${tomorrow()}" required></label><label>Jam pengantaran / pengambilan<input type="time" name="time" value="10:00" min="06:00" max="20:00" required></label></div></section><section class="panel form-panel"><h2>Cara menerima pesanan</h2><div class="delivery-choices"><label><input type="radio" name="method" value="delivery" checked>${icon('truck')}<span>Diantar ke lokasi<small>Radius maksimal 20 km</small></span></label><label><input type="radio" name="method" value="pickup">${icon('bag')}<span>Ambil di dapur<small>Tanpa ongkos kirim</small></span></label></div><div id="delivery-fields"><label>Alamat lengkap<textarea name="address" rows="3" required placeholder="Jalan, nomor rumah, kelurahan, kecamatan">${esc(user?.address||'')}</textarea></label><label>Perkiraan jarak pengiriman<select name="distance"><option value="3">3 km — Menteng</option><option value="8">8 km — dalam jangkauan</option><option value="15">15 km — dalam jangkauan</option><option value="25">25 km — di luar jangkauan</option></select></label><p id="distance-message" class="notice compact">Lokasi dalam jangkauan pengiriman.</p><p class="muted small-text">Perkiraan tarif: Rp15.000 untuk 5 km pertama, lalu Rp2.000/km. Peta dan perhitungan lokasi aktual belum terhubung.</p></div><p id="pickup-message" class="notice" hidden>Ambil di Dapur Menteng, Jakarta Pusat, sesuai jadwal pesanan.</p></section><section class="panel form-panel"><h2>Catatan tambahan</h2><label>Informasi untuk dapur atau kurir (opsional)<textarea name="notes" rows="3" maxlength="500" placeholder="Patokan alamat atau kebutuhan acara"></textarea></label></section></div>${summary(cart,15000,'<button class="button full" type="submit">Buat pesanan '+icon('arrow')+'</button>')}</form></div>`;}
function selectedOrder(){
    if (sData.order) {
        const o = sData.order;
        return {
            id: o.nomor_pesanan || o.order_number || ('DM-' + o.id),
            name: o.nama_penerima || o.recipient_name,
            email: o.email_penerima || o.recipient_email || (o.user?.email || o.pengguna?.email || ''),
            phone: o.nomor_telepon_penerima || o.recipient_phone,
            date: String(o.tanggal_pesanan || o.order_date || o.created_at || '').slice(0, 10),
            deliveryDate: String(o.tanggal_pengiriman || o.delivery_date || '').slice(0, 10),
            time: o.waktu_pengiriman || o.delivery_time || '10:00',
            method: o.jenis_pengiriman || o.delivery_type || 'delivery',
            address: o.alamat_pengiriman || o.delivery_address || 'Ambil di dapur',
            items: (o.items || []).map(it => ({
                id: it.id_menu || it.menu_id,
                name: it.nama_menu || it.menu_name,
                price: Number(it.harga || it.price),
                qty: it.kuantitas || it.quantity,
                note: it.catatan || it.notes || '',
                image: it.menu?.foto_menu || it.menu?.image_path || 'hero.jpg',
            })),
            fee: Number(o.biaya_pengiriman ?? o.delivery_fee ?? 0),
            payment: o.status_pembayaran || o.payment_status || 'Menunggu pembayaran',
            status: Number(o.status_pesanan ?? o.order_status ?? 0),
            proof: o.payment?.bukti_transfer || o.payment?.proof_image || null,
            rejection: o.payment?.catatan_penolakan || o.payment?.rejection_note || null,
        };
    }
    const id=new URLSearchParams(location.search).get('id');
    return orders.find(o=>o.id===id)||orders.find(o=>o.email===(user?.email||'siti@contoh.test'))||null;
}
function payment(){const o=selectedOrder();if(!o)return `<div class="container page-content">${empty('Belum ada pesanan','Buat pesanan sebelum mengunggah bukti transfer.','/menu','Pilih menu')}</div>`;return `<div class="container page-content">${heading('Selesaikan pembayaran','Transfer sesuai tagihan, lalu kirim bukti untuk diperiksa admin.')} ${steps(2)}<div class="notice">${badge(o.payment)} <span>${esc(o.id)} · Nomor rekening belum tersedia. Jangan melakukan transfer.</span></div><div class="two-column"><div><section class="panel form-panel"><h2>Transfer bank</h2><p>Pilih salah satu rekening tujuan berikut.</p><div class="bank-grid">${[['BCA','000 123 4567'],['Mandiri','000 987 654 3210']].map(([b,n])=>`<div class="bank"><strong>${b}</strong><small>Nomor rekening belum tersedia</small></div>`).join('')}</div></section><form id="payment-form" data-id="${o.id}" class="panel form-panel"><h2>Konfirmasi transfer</h2>${o.payment==='Ditolak'?`<p class="notice error">${esc(o.rejection||'Bukti belum sesuai. Periksa nominal dan unggah kembali bukti yang jelas.')}</p>`:''}<div class="form-grid"><label>Bank pengirim<input name="bank" placeholder="Contoh: BCA" required></label><label>Nama pemilik rekening<input name="holder" value="${esc(o.name)}" required></label><label>Nominal transfer<input type="number" name="amount" min="${total(o.items)+o.fee}" value="${total(o.items)+o.fee}" required></label><label>Tanggal transfer<input type="date" name="transferDate" max="${today()}" value="${today()}" required></label></div><label class="upload-area">${icon('bag')}<b>Pilih bukti transfer</b><span>JPG, PNG, atau PDF. Maksimal 2 MB.</span><input name="proof" type="file" accept="image/jpeg,image/png,application/pdf" required></label><div id="proof-preview"></div><p id="payment-error" class="form-error" role="alert"></p><button class="button full" type="submit" ${o.payment==='Lunas'?'disabled':''}>Kirim bukti pembayaran</button></form></div>${summary(o.items,o.fee,button('/lacak-pesanan?id='+o.id,'Lacak pesanan','outline full'))}</div></div>`;}
function customerOrders(){return orders.filter(o=>o.email===(user?.email||'siti@contoh.test'));}
function history(){const list=customerOrders();return `<div class="container page-content">${heading('Pesanan Anda','Dari dapur hingga meja makan, pantau semuanya di sini.',button('/menu','Pesan lagi'))}<div class="tabs history-tabs"><button data-action="history-filter" data-filter="all" aria-pressed="true">Semua pesanan</button><button data-action="history-filter" data-filter="active" aria-pressed="false">Sedang berjalan</button><button data-action="history-filter" data-filter="done" aria-pressed="false">Selesai</button></div><div id="history-list">${historyCards(list)}</div></div>`;}
function historyCards(list){return list.length?list.map(o=>`<article class="panel order-card"><div class="order-card-header"><span><b>${esc(o.id)}</b><small>${date(o.date)}</small></span>${badge(states[o.status])}</div><div class="order-card-body"><img src="/images/${o.items[0].image}" alt="Ilustrasi menu"><div><h2>${esc(o.items[0].name)}</h2><p>${o.items.reduce((n,x)=>n+x.qty,0)} porsi${o.items.length>1?' · '+o.items.length+' menu':''}</p><small>${icon('clock')} ${date(o.deliveryDate)}, ${esc(o.time)}</small></div><strong>${money(total(o.items)+o.fee)}</strong></div><div class="order-card-footer">${badge(o.payment)}${button('/lacak-pesanan?id='+o.id,'Detail & lacak','outline small')}</div></article>`).join(''):empty('Belum ada pesanan di sini','Menu untuk momen berikutnya sudah menanti.','/menu','Pilih menu');}
function tracking(){const o=selectedOrder();if(!o)return `<div class="container page-content">${empty('Belum ada pesanan','Pilih menu untuk mulai memesan.','/menu','Pilih menu')}</div>`;return `<div class="container page-content">${heading('Kabar dari dapur','Informasi dan perkembangan pesanan Anda.',`<button class="button outline" data-action="print">Cetak invoice</button>`)}<div class="panel tracking-panel"><div class="panel-heading"><div><h2>${esc(o.id)}</h2><p>Dipesan ${date(o.date)}</p></div>${badge(o.payment)}</div><ol class="tracking-steps">${states.map((s,i)=>`<li class="${i<=o.status?'complete':''}"><span>${i<=o.status?'✓':i+1}</span><b>${s}</b><small>${i<o.status?'Sudah selesai':i===o.status?'Tahap saat ini':'Belum dimulai'}</small></li>`).join('')}</ol>${o.status===0?button('/pembayaran?id='+o.id,o.payment==='Menunggu verifikasi'?'Lihat konfirmasi pembayaran':'Buka pembayaran','outline'):''}</div><div class="two-column"><section class="panel form-panel"><h2>Penerima & pengiriman</h2><dl class="details-list">${[['Nama',o.name],['WhatsApp',o.phone],['Jadwal',date(o.deliveryDate)+', '+o.time],['Metode',o.method==='pickup'?'Ambil di dapur':'Diantar ke lokasi'],['Alamat',o.method==='pickup'?'Dapur Menteng, Jakarta Pusat':o.address],['Catatan',o.notes||'Tidak ada catatan tambahan']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl></section>${summary(o.items,o.fee,'')}</div><a class="plain-link" href="/pesanan">Kembali ke pesanan Anda</a></div>`;}
function auth(register=false){return `<div class="container auth-layout"><section class="auth-story"><img src="/images/hero.jpg" alt="Ilustrasi sepiring nasi uduk lengkap"><div><h1>${register?'Satu akun.<br>Banyak momen<br>makan bersama.':'Senang bertemu<br>Anda lagi.'}</h1><p>Pesan hidangan favorit dan pantau persiapannya, dari dapur sampai meja makan.</p></div></section><section class="auth-form"><a class="breadcrumb" href="/">Kembali ke beranda</a><h2>${register?'Buat akun Anda':'Masuk ke akun'}</h2><p>${register?'Mulai rencanakan hidangan untuk momen Anda.':'Pesanan dan menu favorit Anda sudah menanti.'}</p><form id="auth-form" method="POST" action="${register?'/register':'/login'}" data-register="${register}"><input type="hidden" name="_token" value="${esc(sData.csrfToken||'')}">${register?'<label>Nama lengkap<input name="nama" autocomplete="name" required></label>':''}<label>Email<input type="email" name="email" autocomplete="email" placeholder="nama@email.com" required></label>${register?'<label>Nomor WhatsApp<input name="nomor_telepon" type="tel" autocomplete="tel" pattern="[0-9+ ()-]{9,18}" placeholder="08xxxxxxxxxx" required></label><label>Alamat di Jakarta<textarea name="alamat" autocomplete="street-address" rows="2" required></textarea></label>':''}<label>Password<div class="password-input"><input type="password" name="password" autocomplete="${register?'new-password':'current-password'}" minlength="8" required><button type="button" class="text-button" data-action="password">Lihat</button></div></label>${register?'<label>Ulangi password<input type="password" name="password_confirmation" autocomplete="new-password" minlength="8" required></label>':''}<p class="form-error" id="auth-error" role="alert" style="${sData.flash?.error?'display:block':''}">${esc(sData.flash?.error||'')}</p><button class="button full" type="submit">${register?'Daftar akun':'Masuk'}</button></form><p class="auth-switch">${register?'Sudah punya akun? <a href="/login">Masuk di sini</a>':'Belum punya akun? <a href="/register">Daftar akun</a>'}</p></section></div>`;}
function orderTable(list,report=false){return `<div class="table-scroll"><table><thead><tr>${['Pesanan','Pelanggan',report?'Porsi':'Jadwal','Total tagihan','Pembayaran','Status',...report?[]:['Aksi']].map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${list.map(o=>`<tr><td><b>${esc(o.id)}</b><small>${date(o.date)}</small></td><td>${esc(o.name)}</td><td>${report?o.items.reduce((a,x)=>a+x.qty,0):date(o.deliveryDate)}</td><td class="nowrap">${money(total(o.items)+o.fee)}</td><td>${badge(o.payment)}</td><td>${badge(states[o.status])}</td>${report?'':`<td><button class="text-button" data-action="order-detail" data-id="${o.id}">Detail</button></td>`}</tr>`).join('')||'<tr><td colspan="7" class="table-empty">Tidak ada pesanan yang sesuai filter.</td></tr>'}</tbody></table></div>`;}
function metrics(list){const paid=list.filter(o=>o.payment==='Lunas');return `<div class="metrics"><article><span>Omzet terverifikasi</span><strong>${money(paid.reduce((a,o)=>a+total(o.items)+o.fee,0))}</strong><small>Dari pembayaran yang telah diperiksa</small></article><article><span>Total pesanan</span><strong>${list.length}</strong><small>Seluruh status pesanan</small></article><article><span>${page==='reports'?'Porsi terjual':'Menunggu verifikasi'}</span><strong>${page==='reports'?paid.reduce((a,o)=>a+o.items.reduce((n,x)=>n+x.qty,0),0):list.filter(o=>o.payment==='Menunggu verifikasi').length}</strong><small>${page==='reports'?'Dari pembayaran terverifikasi':'Bukti transfer perlu diperiksa'}</small></article></div>`;}
function dashboard(){return `<div class="admin-content">${heading('Selamat datang di dapur.','Berikut ringkasan pesanan dan aktivitas usaha Anda.',`<span class="date-chip">${icon('clock')} ${date(today())}</span>`)}${metrics(orders)}<div class="notice action-notice"><div>${icon('bag')}<span><b>${orders.filter(o=>o.payment==='Menunggu verifikasi').length} pembayaran menunggu pemeriksaan</b><small>Periksa bukti transfer sebelum pesanan disiapkan dapur.</small></span></div>${button('/admin/pesanan','Periksa pembayaran','small')}</div><section class="panel table-panel"><div class="panel-heading"><h2>Pesanan terbaru</h2><a href="/admin/pesanan" class="plain-link">Semua pesanan</a></div>${orderTable(orders.slice(0,5))}</section><section class="panel chart-panel"><div class="panel-heading"><h2>Pesanan 7 hari terakhir</h2><span class="muted">Jumlah pesanan per hari</span></div><div class="bar-chart">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);const ds=d.toLocaleDateString('en-CA');const n=orders.filter(o=>o.date===ds).length;return `<div><b>${n}</b><span style="height:${Math.max(n*38,3)}px"></span><small>${d.toLocaleDateString('id-ID',{day:'numeric',month:'short'})}</small></div>`;}).join('')}</div></section></div>`;}
function adminMenus(){return `<div class="admin-content">${heading('Menu & paket','Kelola hidangan, harga, dan ketersediaan untuk pelanggan.','<button class="button" data-action="edit-menu">+ Tambah menu</button>')}<section class="panel table-panel"><div class="panel-heading"><h2>${menus.length} menu di dapur</h2><span class="muted">3 pilihan penyajian</span></div><div class="table-scroll"><table><thead><tr>${['Menu','Kategori','Harga / porsi','Minimum','Ketersediaan','Aksi'].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${menus.map(m=>`<tr><td><div class="table-menu"><img src="/images/${m.image}" alt=""><b>${esc(m.name)}</b></div></td><td>${cats[m.category]}</td><td>${money(m.price)}</td><td>${m.min} porsi</td><td><button class="availability ${m.available?'on':''}" data-action="availability" data-id="${m.id}" aria-pressed="${m.available}"><span></span>${m.available?'Tersedia':'Nonaktif'}</button></td><td><div class="table-actions"><button class="text-button" data-action="edit-menu" data-id="${m.id}">Edit</button><button class="text-button remove" data-action="delete-menu" data-id="${m.id}">Hapus</button></div></td></tr>`).join('')}</tbody></table></div></section><p class="muted small-text">Menu nonaktif tidak ditampilkan di katalog pelanggan.</p></div>`;}
function editMenu(id){const m=menus.find(x=>x.id===id)||{name:'',category:'satuan',price:18000,min:1,desc:'',image:'satuan.jpg'};showModal(`<form id="menu-form" data-id="${id||''}" class="modal-form"><h2 id="modal-title">${id?'Edit menu':'Tambah menu'}</h2><label>Nama menu<input name="name" value="${esc(m.name)}" maxlength="100" required></label><div class="form-grid"><label>Kategori<select name="category">${Object.entries(cats).map(([k,n])=>`<option value="${k}" ${m.category===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Minimum porsi<input name="min" type="number" min="1" step="1" value="${m.min}" required></label><label>Harga per porsi<input name="price" type="number" min="1000" step="500" value="${m.price}" required></label><label>Foto ilustrasi<select name="image">${['hero.jpg','satuan.jpg','box.jpg','prasmanan.jpg'].map((s,i)=>`<option value="${s}" ${s===m.image?'selected':''}>Pilihan ${i+1}</option>`).join('')}</select></label></div><label>Komposisi lauk<textarea name="desc" rows="3" maxlength="500" required>${esc(m.desc)}</textarea></label><button class="button full" type="submit">Simpan menu</button></form>`);}
function adminOrders(){return `<div class="admin-content">${heading('Pesanan masuk','Periksa pembayaran dan kelola persiapan setiap pesanan.')}<form id="order-filter" class="panel filter-bar"><label>Cari pesanan<input name="search" type="search" placeholder="Nomor pesanan atau nama"></label><label>Status pesanan<select name="status"><option value="">Semua status</option>${states.map((s,i)=>`<option value="${i}">${s}</option>`).join('')}</select></label><label>Pembayaran<select name="payment"><option value="">Semua pembayaran</option>${['Menunggu pembayaran','Menunggu verifikasi','Lunas','Ditolak'].map(s=>`<option>${s}</option>`).join('')}</select></label><button class="button" type="submit">Terapkan</button><button type="reset" class="text-button">Reset</button></form><section class="panel table-panel" id="orders-table">${orderTable(orders)}</section></div>`;}
function orderDetail(id){const o=orders.find(x=>x.id===id);if(!o)return;showModal(`<div class="modal-form"><h2 id="modal-title">${esc(o.id)}</h2><p>${esc(o.name)} · ${date(o.deliveryDate)}, ${esc(o.time)}</p>${summary(o.items,o.fee,'')}<p><b>Pengiriman:</b> ${esc(o.method==='pickup'?'Ambil di dapur':o.address)}</p><p><b>Pembayaran:</b> ${badge(o.payment)}</p><p><b>Bukti:</b> ${esc(o.proof||'Belum diunggah')}</p>${o.proofData?.startsWith('data:image/')?`<img class="payment-proof" src="${esc(o.proofData)}" alt="Bukti transfer">`:o.proofData?.startsWith('data:application/pdf')?`<a class="plain-link" href="${esc(o.proofData)}" download="bukti-transfer.pdf">Unduh bukti PDF</a>`:''}${o.payment==='Menunggu verifikasi'?`<div class="form-grid"><button class="button" data-action="verify" data-id="${o.id}">Terima pembayaran</button><button class="button outline" data-action="reject" data-id="${o.id}">Tolak bukti</button></div>`:''}<form id="status-form" data-id="${o.id}"><label>Progres pesanan<select name="status" ${o.payment!=='Lunas'?'disabled':''}>${states.map((s,i)=>`<option value="${i}" ${o.status===i?'selected':''}>${s}</option>`).join('')}</select></label><button class="button full" type="submit" ${o.payment!=='Lunas'?'disabled':''}>Simpan progres</button></form></div>`);}
function customerPage(){const list=[...customers,...read('accounts',[])];return `<div class="admin-content">${heading('Pelanggan','Kenali pelanggan dan lihat riwayat pesanannya.')}<section class="panel table-panel"><div class="panel-heading"><h2>${list.length} pelanggan terdaftar</h2></div><div class="table-scroll"><table><thead><tr>${['Pelanggan','WhatsApp','Pesanan','Total belanja','Aksi'].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${list.map((c,i)=>{const os=orders.filter(o=>o.email===c.email);return `<tr><td><b>${esc(c.name)}</b><small>${esc(c.email)}</small></td><td>${esc(c.phone)}</td><td>${os.length} transaksi</td><td>${money(os.filter(o=>o.payment==='Lunas').reduce((a,o)=>a+total(o.items)+o.fee,0))}</td><td><button class="text-button" data-action="customer" data-index="${i}">Lihat riwayat</button></td></tr>`;}).join('')}</tbody></table></div></section></div>`;}
let reportList=orders;
function reports(){return `<div class="admin-content">${heading('Laporan penjualan','Tinjau transaksi dan omzet sesuai periode yang Anda pilih.')}<form id="report-filter" class="panel filter-bar"><label>Tanggal mulai<input name="start" type="date" value="2026-11-01" required></label><label>Tanggal akhir<input name="end" type="date" value="${today()}" required></label><label>Status<select name="status"><option value="">Semua status</option>${states.map((s,i)=>`<option value="${i}">${s}</option>`).join('')}</select></label><button class="button">Terapkan filter</button></form><div id="report-results"></div></div>`;}
function renderReport(){const f=$('#report-filter');if(f){const d=new FormData(f);reportList=orders.filter(o=>o.date>=d.get('start')&&o.date<=d.get('end')&&(d.get('status')===''||o.status===Number(d.get('status'))));}$('#report-results').innerHTML=`${metrics(reportList)}<section class="panel table-panel"><div class="panel-heading"><div><h2>Rincian transaksi</h2><p>${reportList.length} transaksi sesuai periode pilihan</p></div><div class="table-actions"><button class="button outline small" data-action="print">Cetak / PDF</button><button class="button small" data-action="export">Unduh CSV</button></div></div>${orderTable(reportList,true)}</section><p class="muted small-text">Omzet dan porsi terjual dihitung dari pembayaran terverifikasi. CSV dapat dibuka di Excel.</p>`;}
function render(){const views={home,catalog,cart:cartPage,checkout,payment,history,tracking,login:()=>auth(),register:()=>auth(true),dashboard,'admin-menu':adminMenus,'admin-orders':adminOrders,customers:customerPage,reports};$('#main').innerHTML=(views[page]||home)();if(page==='reports')renderReport();document.title=({home:'Nasi uduk untuk makan bersama',catalog:'Pilihan menu',cart:'Keranjang',checkout:'Checkout',payment:'Pembayaran',history:'Pesanan Anda',tracking:'Lacak pesanan',login:'Masuk',register:'Daftar akun',dashboard:'Ringkasan admin','admin-menu':'Menu & paket','admin-orders':'Pesanan masuk',customers:'Pelanggan',reports:'Laporan penjualan'}[page]||'Beranda')+' — Dapur Menteng';}
function persistCart(){save('cart',cart);headerCount();}
function headerCount(){const count=$('.cart-count');if(count)count.textContent=cart.reduce((a,x)=>a+x.qty,0);}
function persistOrders(){save('orders',orders);}
function shipping(){const f=$('#checkout-form');if(!f)return 0;const pickup=f.elements.method.value==='pickup';const distance=Number(f.elements.distance.value);$('#delivery-fields').hidden=pickup;$('#pickup-message').hidden=!pickup;f.elements.address.required=!pickup;const invalid=!pickup&&distance>20;$('#distance-message').textContent=invalid?'Lokasi di luar radius 20 km. Pilih ambil di dapur atau alamat dalam jangkauan.':'Lokasi dalam jangkauan pengiriman.';$('#distance-message').classList.toggle('error',invalid);f.querySelector('[type="submit"]').disabled=invalid;const fee=pickup?0:15000+Math.max(0,distance-5)*2000;$('#shipping-cost').textContent=money(fee);$('#grand-total').textContent=money(total(cart)+fee);return fee;}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=Number(el.dataset.id),i=Number(el.dataset.index);
 if(a==='close')$('#modal').close();
 if(a==='nav'){const expanded=el.getAttribute('aria-expanded')==='true';el.setAttribute('aria-expanded',!expanded);$('#navigation').classList.toggle('open',!expanded);}
 if(a==='category'){activeCategory=el.dataset.category;window.history.replaceState(null,'','/menu?kategori='+activeCategory);render();}
 if(a==='detail')detail(id);
 if(a==='qty'){cart[i].qty=Math.max(cart[i].min,cart[i].qty+Number(el.dataset.delta));persistCart();render();}
 if(a==='remove'){cart.splice(i,1);persistCart();render();toast('Menu dihapus dari keranjang.');}
 if(a==='password'){const input=el.previousElementSibling;input.type=input.type==='password'?'text':'password';el.textContent=input.type==='password'?'Lihat':'Sembunyikan';}
 if(a==='logout'){const f=document.createElement('form');f.method='POST';f.action='/logout';f.innerHTML=`<input type="hidden" name="_token" value="${esc(sData.csrfToken||'')}">`;document.body.appendChild(f);localStorage.removeItem('menteng-user');f.submit();return;}
 if(a==='copy'){try{await navigator.clipboard.writeText(el.dataset.value);toast('Nomor rekening disalin.');}catch{toast('Nomor rekening: '+el.dataset.value);}}
 if(a==='history-filter'){document.querySelectorAll('[data-action="history-filter"]').forEach(b=>b.setAttribute('aria-pressed',b===el));$('#history-list').innerHTML=historyCards(customerOrders().filter(o=>el.dataset.filter==='all'||(el.dataset.filter==='done'?o.status===3:o.status<3)));}
 if(a==='print')window.print();
 if(a==='edit-menu')editMenu(id);
 if(a==='availability'){const m=menus.find(m=>m.id===id);m.available=!m.available;save('menus',menus);render();toast('Ketersediaan menu diperbarui.');}
 if(a==='delete-menu')showModal(`<div class="modal-form"><h2 id="modal-title">Hapus menu ini?</h2><p>Menu akan dihapus dari katalog. Pesanan yang sudah dibuat tetap tersimpan.</p><button class="button" data-action="confirm-delete" data-id="${id}">Hapus menu</button> <button class="button outline" data-action="close">Batal</button></div>`);
 if(a==='confirm-delete'){menus=menus.filter(m=>m.id!==id);save('menus',menus);$('#modal').close();render();toast('Menu dihapus.');}
 if(a==='order-detail')orderDetail(el.dataset.id);
 if(a==='verify'){const o=orders.find(o=>o.id===el.dataset.id);o.payment='Lunas';o.status=1;persistOrders();$('#modal').close();render();toast('Pembayaran diterima. Pesanan masuk antrean dapur.');}
 if(a==='reject'){showModal(`<form id="reject-form" data-id="${esc(el.dataset.id)}" class="modal-form"><h2 id="modal-title">Tolak bukti pembayaran</h2><label>Alasan penolakan<textarea name="reason" rows="3" maxlength="500" placeholder="Jelaskan apa yang perlu diperbaiki pelanggan" required></textarea></label><button class="button full">Kirim alasan penolakan</button></form>`);}
 if(a==='customer'){const c=[...customers,...read('accounts',[])][i];showModal(`<div class="modal-form"><h2 id="modal-title">${esc(c.name)}</h2><p>${esc(c.email)}<br>${esc(c.phone)}</p>${historyCards(orders.filter(o=>o.email===c.email))}</div>`);}
 if(a==='export'){const cells=[['Invoice','Tanggal','Pelanggan','Porsi','Total tagihan','Pembayaran','Status'],...reportList.map(o=>[o.id,o.date,o.name,o.items.reduce((n,x)=>n+x.qty,0),total(o.items)+o.fee,o.payment,states[o.status]])];const csv='\uFEFF'+cells.map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='laporan-dapur-menteng.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Laporan CSV diunduh.');}
});
document.addEventListener('input',e=>{if(e.target.id==='menu-search'){const q=e.target.value.toLowerCase();const list=menus.filter(m=>m.available&&m.category===activeCategory&&(m.name+' '+m.desc).toLowerCase().includes(q));$('#menu-grid').innerHTML=list.map(menuCard).join('')||empty('Menu belum ditemukan','Coba nama lauk lain atau ganti kategori.');}});
document.addEventListener('change',e=>{
 if(e.target.matches('[data-cart-note]')){cart[Number(e.target.dataset.cartNote)].note=e.target.value;persistCart();}
 if(e.target.matches('[data-cart-qty]')){const x=cart[Number(e.target.dataset.cartQty)];const n=Number(e.target.value);x.qty=Number.isInteger(n)?Math.max(x.min,n):x.min;persistCart();render();}
 if(e.target.closest('#checkout-form'))shipping();
 if(e.target.name==='proof'){const file=e.target.files[0];$('#proof-preview').innerHTML='';$('#payment-error').textContent='';if(!file)return;if(!['image/jpeg','image/png','application/pdf'].includes(file.type)||file.size>2*1024*1024){e.target.value='';$('#payment-error').textContent='Pilih JPG, PNG, atau PDF dengan ukuran maksimal 2 MB.';return;}if(file.type.startsWith('image/')){const img=document.createElement('img');img.alt='Pratinjau bukti transfer';img.src=URL.createObjectURL(file);img.onload=()=>URL.revokeObjectURL(img.src);$('#proof-preview').append(img);}else $('#proof-preview').textContent=file.name;}
});
document.addEventListener('reset',e=>{if(e.target.id==='order-filter')setTimeout(()=>$('#orders-table').innerHTML=orderTable(orders),0);});
document.addEventListener('submit',async e=>{const f=e.target;
 if(f.id==='auth-form'){
  const register=f.dataset.register==='true';
  if(register){
   const pass=f.querySelector('[name="password"]')?.value;
   const conf=f.querySelector('[name="password_confirmation"]')?.value;
   if(pass&&conf&&pass!==conf){
    e.preventDefault();
    const err=$('#auth-error');if(err){err.textContent='Konfirmasi password belum sama.';err.style.display='block';}
    return;
   }
  }
  localStorage.removeItem('menteng-user');
  return;
 }
 e.preventDefault();const d=new FormData(f);
 if(f.id==='add-form'){const m=menus.find(x=>x.id===Number(f.dataset.id));const qty=Number(d.get('qty'));if(!Number.isInteger(qty)||qty<m.min)return;const found=cart.find(x=>x.id===m.id&&x.note===d.get('note'));if(found)found.qty+=qty;else cart.push({...m,qty,note:d.get('note')});persistCart();$('#modal').close();toast(`${qty} porsi ditambahkan ke keranjang.`);}
 if(f.id==='checkout-form'){const fee=shipping();if(f.querySelector('[type="submit"]').disabled)return;if(d.get('deliveryDate')<tomorrow()){toast('Pilih tanggal acara paling awal besok.');return;}const o={...Object.fromEntries(d),id:'DM-'+Date.now().toString().slice(-10),date:today(),email:user?.email||'siti@contoh.test',items:structuredClone(cart),fee,payment:'Menunggu pembayaran',status:0};orders.unshift(o);persistOrders();cart=[];persistCart();location.href='/pembayaran?id='+o.id;}
 if(f.id==='payment-form'){const o=orders.find(x=>x.id===f.dataset.id);const file=d.get('proof');if(!file.size||file.size>2*1024*1024||!['image/jpeg','image/png','application/pdf'].includes(file.type)){$('#payment-error').textContent='Pilih JPG, PNG, atau PDF maksimal 2 MB.';return;}if(Number(d.get('amount'))!==total(o.items)+o.fee){$('#payment-error').textContent='Nominal transfer harus sama dengan total tagihan.';return;}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const previous={...o};Object.assign(o,{payment:'Menunggu verifikasi',proof:file.name,proofData:data,bank:d.get('bank'),holder:d.get('holder'),transferDate:d.get('transferDate')});try{persistOrders();location.href='/lacak-pesanan?id='+o.id;}catch{Object.assign(o,previous);$('#payment-error').textContent='Penyimpanan browser penuh. Pilih bukti dengan ukuran lebih kecil.';}}
 if(f.id==='menu-form'){const id=Number(f.dataset.id);const values={...Object.fromEntries(d),price:Number(d.get('price')),min:Number(d.get('min'))};if(id)Object.assign(menus.find(x=>x.id===id),values);else menus.push({...values,id:Date.now(),available:true});save('menus',menus);$('#modal').close();render();toast('Menu disimpan.');}
 if(f.id==='status-form'){const o=orders.find(x=>x.id===f.dataset.id);if(o.payment!=='Lunas')return;o.status=Number(d.get('status'));persistOrders();$('#modal').close();render();toast('Progres pesanan diperbarui.');}
 if(f.id==='reject-form'){const o=orders.find(x=>x.id===f.dataset.id);o.payment='Ditolak';o.rejection=d.get('reason');persistOrders();$('#modal').close();render();toast('Bukti ditolak. Alasan tersedia untuk pelanggan.');}
 if(f.id==='order-filter'){const q=String(d.get('search')).toLowerCase();$('#orders-table').innerHTML=orderTable(orders.filter(o=>(o.id+' '+o.name).toLowerCase().includes(q)&&(d.get('status')===''||o.status===Number(d.get('status')))&&(!d.get('payment')||o.payment===d.get('payment'))));}
 if(f.id==='report-filter'){if(d.get('start')>d.get('end')){toast('Tanggal akhir harus setelah tanggal mulai.');return;}renderReport();}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
header();render();
if(sData.flash?.success){setTimeout(()=>toast(sData.flash.success),150);}
if(sData.flash?.error){setTimeout(()=>toast(sData.flash.error),150);}
})();

